export const learningUiDictionaries = { de, en, it, es, fr } satisfies Record<
  AppLocale,
  LearningUiDictionary
>;

export type LearningUiCopy = (
  key: LearningUiKey,
  values?: Readonly<Record<string, string | number>>,
) => string;

export function getLearningUiCopy(locale: AppLocale): LearningUiCopy {
  const dictionary = learningUiDictionaries[locale];
  return (key, values) =>
    dictionary[key].replace(/\{([A-Za-z][A-Za-z0-9]*)\}/g, (token, name) =>
      values && name in values ? String(values[name]) : token,
    );
}

export function formatLearningExamDuration(
  seconds: number | null,
  locale: AppLocale,
) {
  if (seconds === null) return getLearningUiCopy(locale)("exam.noTimeLimit");
  const totalMinutes = Math.max(1, Math.ceil(seconds / 60));
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  const formatUnit = (value: number, unit: "hour" | "minute") =>
    new Intl.NumberFormat(intlLocale(locale), {
      style: "unit",
      unit,
      unitDisplay: "short",
      maximumFractionDigits: 0,
    }).format(value);
  return [
    hours ? formatUnit(hours, "hour") : "",
    minutes || !hours ? formatUnit(minutes || totalMinutes, "minute") : "",
  ]
    .filter(Boolean)
    .join(" ");
}

export function formatLearningFileSize(bytes: number, locale: AppLocale) {
  const bounded = Math.max(0, bytes);
  const units = ["byte", "kilobyte", "megabyte", "gigabyte"] as const;
  let value = bounded;
  let unitIndex = 0;
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex += 1;
  }
  return new Intl.NumberFormat(intlLocale(locale), {
    style: "unit",
    unit: units[unitIndex],
    unitDisplay: "short",
    maximumFractionDigits: unitIndex === 0 ? 0 : 1,
  }).format(value);
}
